import json, random, subprocess, sys, itertools

CAND = '/workspace/submission/main.py'

def run(lines):
    data = ''.join(json.dumps(l) + '\n' for l in lines)
    r = subprocess.run([sys.executable, '-I', '-B', CAND], input=data, text=True, capture_output=True, timeout=120)
    assert r.returncode == 0, r.stderr
    return [json.loads(x) for x in r.stdout.splitlines()]

def brute(req):
    """Independent reference: returns (best_benefit, best_count) or 'infeasible'."""
    cap = req['capacities']
    warmup = req['warmup']
    pinned = set(req['pinned'])
    flows = req['flows']
    # flow benefit via direct simulation of warmup over chronological runs
    ben = {}
    for f in flows:
        H = len(f['template']) // 2
        kinds = f['kinds']
        N = len(f['path']); h = N - 1
        D = kinds.count('D')
        per = (H - 4 - D) * N
        t_off = kinds.index('T'); q_off = kinds.index('Q')
        k_off = [i for i, c in enumerate(kinds) if c == 'K']
        tmpl = bytes.fromhex(f['template'])
        left = warmup
        elig = 0
        for run in req['offers'][f['id']]:
            hdr = bytes.fromhex(run['header'])
            c = run['count']
            sent = 0
            while sent < c:
                if left > 0:
                    left -= 1
                else:
                    okk = all(hdr[i] == tmpl[i] for i in k_off)
                    if okk and hdr[q_off] <= 7 and hdr[t_off] > h:
                        elig += 1
                sent += 1
        ben[f['id']] = per * elig
    # pinned feasibility
    for f in flows:
        if f['id'] in pinned:
            for nd in f['path']:
                pass
    use = {}
    for f in flows:
        if f['id'] in pinned:
            for nd in f['path']:
                use[nd] = use.get(nd, 0) + 1
    for nd, c in use.items():
        if c > cap[nd]:
            return 'infeasible'
    ids = [f['id'] for f in flows]
    fmap = {f['id']: f for f in flows}
    best = (-1, 10**9)
    for r in range(len(ids) + 1):
        for sub in itertools.combinations(ids, r):
            s = set(sub)
            if not pinned <= s:
                continue
            u = {}
            ok = True
            for fid in s:
                for nd in fmap[fid]['path']:
                    u[nd] = u.get(nd, 0) + 1
                    if u[nd] > cap[nd]:
                        ok = False
                        break
                if not ok:
                    break
            if not ok:
                continue
            b = sum(ben[fid] for fid in s)
            key = (b, -len(s))
            if (b, -len(s)) > (best[0], -best[1]):
                best = (b, len(s))
    return best  # (benefit, count)

def check(req, got):
    ref = brute(req)
    if ref == 'infeasible':
        return got == {'infeasible': True}, 'infeasible-mismatch'
    if 'infeasible' in got:
        return False, 'got-infeasible'
    # verify selected set well-formed, feasible, includes pinned
    sel = got['selected']
    if sel != sorted(set(sel)):
        return False, 'not-sorted-distinct'
    fmap = {f['id']: f for f in req['flows']}
    if not set(req['pinned']) <= set(sel):
        return False, 'pinned-missing'
    u = {}
    for fid in sel:
        if fid not in fmap:
            return False, 'unknown-flow'
        for nd in fmap[fid]['path']:
            u[nd] = u.get(nd, 0) + 1
            if u[nd] > req['capacities'][nd]:
                return False, 'capacity-violated'
    # recompute benefit
    warmup = req['warmup']
    total = 0
    for fid in sel:
        f = fmap[fid]
        H = len(f['template']) // 2
        kinds = f['kinds']
        N = len(f['path']); h = N - 1
        per = (H - 4 - kinds.count('D')) * N
        t_off = kinds.index('T'); q_off = kinds.index('Q')
        k_off = [i for i, c in enumerate(kinds) if c == 'K']
        tmpl = bytes.fromhex(f['template'])
        left = warmup
        elig = 0
        for run in req['offers'][fid]:
            hdr = bytes.fromhex(run['header'])
            c = run['count']
            # chunked warmup consumption (independent formulation)
            skip = min(c, left)
            left -= skip
            rest = c - skip
            if rest and all(hdr[i] == tmpl[i] for i in k_off) and hdr[q_off] <= 7 and hdr[t_off] > h:
                elig += rest
        total += per * elig
    if got['saved'] != total:
        return False, f"saved-mismatch got={got['saved']} exp={total}"
    if total != ref[0]:
        return False, f"benefit-not-optimal got={total} opt={ref[0]}"
    if len(sel) != ref[1]:
        return False, f"count-not-minimal got={len(sel)} min={ref[1]}"
    return True, 'ok'

def gen(rng, n, nodes, pincap=0.3, maxruns=4):
    caps = {nd: rng.randint(0, 4) for nd in nodes}
    flows = []
    for i in range(n):
        ln = rng.randint(2, min(4, len(nodes)))
        path = rng.sample(nodes, ln)
        H = rng.randint(8, 14)
        # build kinds: exactly one Q, one T, >=1 K, 4 + D < H
        slots = list(range(H))
        rng.shuffle(slots)
        qi = slots.pop(); ti = slots.pop()
        nD = rng.randint(0, H - 5)
        kcount = H - 2 - nD - rng.randint(0, max(0, H - 2 - nD - 1))
        kcount = max(1, kcount)
        dslots = [slots.pop() for _ in range(min(nD, len(slots) - 1))]
        kslots = [slots.pop() for _ in range(min(kcount, len(slots)))]
        kinds = ['Z'] * H
        kinds[qi] = 'Q'; kinds[ti] = 'T'
        for s in dslots: kinds[s] = 'D'
        for s in kslots: kinds[s] = 'K'
        kinds = ''.join(kinds)
        assert kinds.count('Q') == 1 and kinds.count('T') == 1 and kinds.count('K') >= 1
        assert 4 + kinds.count('D') < H
        tmpl = bytes(rng.randint(0, 255) for _ in range(H))
        flows.append(dict(id=f'f{i}', path=path, template=tmpl.hex(), kinds=kinds))
    fmap = {f['id']: f for f in flows}
    offers = {}
    for f in flows:
        H = len(f['template']) // 2
        kinds = f['kinds']
        k_off = [i for i, c in enumerate(kinds) if c == 'K']
        t_off = kinds.index('T'); q_off = kinds.index('Q')
        runs = []
        for _ in range(rng.randint(1, maxruns)):
            base = bytearray.fromhex(f['template'])
            if rng.random() < 0.6:
                # matching K
                pass
            else:
                # mismatch at a K position (if any)
                pos = k_off[rng.randrange(len(k_off))]
                base[pos] ^= 0xFF
            if rng.random() < 0.15:
                base[q_off] = rng.randint(8, 255)
            else:
                base[q_off] = rng.randint(0, 7)
            base[t_off] = rng.randint(0, len(f['path']) + 2)
            runs.append(dict(header=base.hex(), count=rng.randint(1, 8)))
        offers[f['id']] = runs
    pinned = [f['id'] for f in flows if rng.random() < pincap]
    # ensure pinned alone feasible sometimes; else it's an infeasible case - fine either way
    return dict(mode='plan', capacities=caps, flows=flows,
                warmup=rng.randint(0, 6), pinned=pinned, offers=offers)

rng = random.Random(12345)
