import json, random, subprocess, sys

CAND = '/workspace/submission/main.py'

def run(lines):
    data = ''.join(json.dumps(l) + '\n' for l in lines)
    r = subprocess.run([sys.executable, '-I', '-B', CAND], input=data, text=True, capture_output=True, timeout=120)
    assert r.returncode == 0, r.stderr
    return [json.loads(x) for x in r.stdout.splitlines()]

# ------- independent reference model (written from spec, different structure) -------
class Model:
    def __init__(self, caps, flows):
        self.caps = caps
        self.fl = {f['id']: f for f in flows}
        self.tbl = {}      # (node,label) -> fid
        self.on = set()    # enabled
    def entry_count(self, node):
        return sum(1 for (n, l) in self.tbl if n == node)
    def step(self, ev):
        op = ev['op']
        if op == 'put':
            fid = ev['flow']; node = ev['node']
            f = self.fl[fid]
            lab = f['labels'][f['path'].index(node)]
            key = (node, lab)
            holder = self.tbl.get(key)
            if holder == fid:
                return {'status': 'ok'}
            if holder is not None and holder in self.on:
                return {'status': 'busy'}
            if key not in self.tbl and self.entry_count(node) >= self.caps[node]:
                return {'status': 'full'}
            self.tbl[key] = fid
            return {'status': 'ok'}
        if op == 'enable':
            fid = ev['flow']
            if fid in self.on:
                return {'status': 'ok'}
            f = self.fl[fid]
            for i, node in enumerate(f['path']):
                if self.tbl.get((node, f['labels'][i])) != fid:
                    return {'status': 'unready'}
            self.on.add(fid)
            return {'status': 'ok'}
        if op == 'disable':
            self.on.discard(ev['flow'])
            return {'status': 'ok'}
        if op == 'reset':
            self.on = set()
            return {'status': 'ok'}
        if op == 'packet':
            return self.pkt(self.fl[ev['flow']], ev['header'], ev['payload'])
    def pkt(self, f, hx, px):
        H = bytes.fromhex(hx); P = bytes.fromhex(px)
        kinds = f['kinds']; T = f['template']
        tb = bytes.fromhex(T)
        qpos = kinds.index('Q'); tpos = kinds.index('T')
        kbad = any(H[i] != tb[i] for i, c in enumerate(kinds) if c == 'K')
        if f['id'] not in self.on:
            mode, reason = 'ip', 'disabled'
        elif kbad:
            mode, reason = 'ip', 'mismatch'
        elif H[qpos] > 7:
            mode, reason = 'ip', 'qos'
        else:
            mode, reason = 'mpls', 'compressed'
        n = len(f['path'])
        tt = H[tpos]
        frames = []
        if tt != 0:
            for hop in range(n):
                if hop > 0:
                    arrived = tt - (hop - 1)
                    if arrived <= 1:
                        break
                link_ttl = tt - hop
                if mode == 'mpls':
                    q = H[qpos]
                    res = bytes(H[i] for i, c in enumerate(kinds) if c == 'D')
                    lbl = f['labels'][hop]
                    hdr4 = ((lbl << 12) | (q << 9) | (1 << 8) | link_ttl).to_bytes(4, 'big')
                    frames.append(hdr4 + res + P)
                else:
                    hh = bytearray(H); hh[tpos] = link_ttl
                    frames.append(bytes(hh) + P)
        delivered = None
        if len(frames) == n:
            if mode == 'mpls':
                out = bytearray(f['H'])
                for i, c in enumerate(kinds):
                    if c == 'K':
                        out[i] = tb[i]
                    elif c == 'Z':
                        out[i] = 0
                    elif c == 'Q':
                        out[i] = H[qpos]
                    elif c == 'T':
                        out[i] = tt - (n - 1)
                dvals = [H[i] for i, c in enumerate(kinds) if c == 'D']
                di = 0
                for i, c in enumerate(kinds):
                    if c == 'D':
                        out[i] = dvals[di]; di += 1
                delivered = (bytes(out) + P).hex()
            else:
                delivered = frames[-1].hex()
        return {'mode': mode, 'reason': reason, 'wire': [x.hex() for x in frames],
                'delivered': delivered, 'byte_hops': sum(len(x) for x in frames)}
    def dump(self):
        active = sorted(self.on)
        tabs = [{'node': k[0], 'label': k[1], 'flow': v}
                for k, v in sorted(self.tbl.items(), key=lambda kv: (kv[0][0], kv[0][1]))]
        return active, tabs

def gen_replay(rng):
    nnodes = rng.randint(2, 5)
    nodes = ['n%d' % i for i in range(nnodes)]
    caps = {nd: rng.randint(0, 3) for nd in nodes}
    nf = rng.randint(1, 4)
    flows = []
    for i in range(nf):
        ln = rng.randint(2, min(4, nnodes))
        path = rng.sample(nodes, ln)
        H = rng.randint(8, 12)
        slots = list(range(H)); rng.shuffle(slots)
        qi = slots.pop(); ti = slots.pop()
        nD = rng.randint(0, H - 5)
        kinds = ['Z'] * H
        kinds[qi] = 'Q'; kinds[ti] = 'T'
        for _ in range(nD):
            kinds[slots.pop()] = 'D'
        for _ in range(max(1, min(len(slots), rng.randint(1, 3)))):
            kinds[slots.pop()] = 'K'
        kinds = ''.join(kinds)
        tmpl = bytes(rng.randint(0, 255) for _ in range(H))
        labels = [rng.randint(16, 40) for _ in path]  # heavy collisions on purpose
        flows.append(dict(id='f%d' % i, path=path, labels=labels, template=tmpl.hex(), kinds=kinds))
    evs = []
    for _ in range(rng.randint(1, 40)):
        op = rng.choice(['put', 'enable', 'disable', 'reset', 'packet'])
        if op == 'put':
            f = flows[rng.randrange(nf)]
            evs.append(dict(op='put', flow=f['id'], node=f['path'][rng.randrange(len(f['path']))]))
        elif op in ('enable', 'disable'):
            evs.append(dict(op=op, flow=flows[rng.randrange(nf)]['id']))
        elif op == 'reset':
            evs.append(dict(op='reset'))
        else:
            f = flows[rng.randrange(nf)]
            hb = bytearray.fromhex(f['template'])
            kinds = f['kinds']
            if rng.random() < 0.25:
                ki = [i for i, c in enumerate(kinds) if c == 'K']
                hb[ki[rng.randrange(len(ki))]] ^= 0xFF
            hb[kinds.index('Q')] = rng.randint(0, 255)
            hb[kinds.index('T')] = rng.randint(0, 255)
            pay = bytes(rng.randint(0, 255) for _ in range(rng.randint(0, 6)))
            evs.append(dict(op='packet', flow=f['id'], header=hb.hex(), payload=pay.hex()))
    return dict(mode='replay', capacities=caps, flows=flows, events=evs)

rng = random.Random(987)
batch = [gen_replay(rng) for _ in range(400)]
got = run(batch)
fails = 0
for t, (req, g) in enumerate(zip(batch, got)):
    m = Model(req['capacities'], req['flows'])
    exp_results = [m.step(ev) for ev in req['events']]
    active, tabs = m.dump()
    exp = {'results': exp_results, 'active': active, 'tables': tabs}
    if exp != g:
        fails += 1
        if fails <= 3:
            print('FAIL', t)
            print(json.dumps(req)[:600])
            print('exp:', json.dumps(exp)[:400])
            print('got:', json.dumps(g)[:400])
print('replay fuzz cases:', len(batch), 'failures:', fails)
